using System.Text.Json;
using System.Text.RegularExpressions;
using Sedna.UI.Tests.TestSupport;

namespace Sedna.UI.Tests;

/// <summary>
/// The token export in the Design Tokens Community Group format: <c>Sedna.UI.tokens.dtcg*.json</c>,
/// generated by <c>build/export-tokens.sh</c> from the blocks export and committed beside it.
/// </summary>
/// <remarks>
/// <c>The_token_export_matches_the_stylesheet</c> holds the blocks export to the stylesheet; these
/// hold the DTCG files to the blocks export, and to the format: every token typed, every value in
/// its type's shape, every alias resolving in the files a reader loads with it.
/// </remarks>
public class DtcgTokenExportTests
{
    private const string Extension = "com.sedna-ui";
    private const string BaseFile = "Sedna.UI.tokens.dtcg.json";

    private static readonly HashSet<string> Types = new(StringComparer.Ordinal)
    {
        "color", "dimension", "duration", "fontFamily", "fontWeight", "number", "cubicBezier", "shadow",
    };

    private static readonly Regex Alias = new(@"^\{(?<path>[\w-]+\.[\w-]+)\}$", RegexOptions.Compiled);

    private static string TokensDir => Path.GetDirectoryName(Assets.TokensPath)!;

    private static JsonElement Load(string file) =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(TokensDir, file))).RootElement;

    private static JsonElement Meta(JsonElement doc) =>
        doc.GetProperty("$extensions").GetProperty(Extension);

    /// <summary>The base file first, then every mode in the order the manifest lists them.</summary>
    private static List<(string File, string Selector, string? Media, List<string> Load)> Files()
    {
        var files = new List<(string, string, string?, List<string>)> { (BaseFile, ":root", null, []) };
        foreach (var mode in Meta(Load(BaseFile)).GetProperty("modes").EnumerateArray())
            files.Add((
                mode.GetProperty("file").GetString()!,
                mode.GetProperty("selector").GetString()!,
                mode.GetProperty("media").ValueKind == JsonValueKind.Null ? null : mode.GetProperty("media").GetString(),
                mode.GetProperty("load").EnumerateArray().Select(f => f.GetString()!).ToList()));
        return files;
    }

    /// <summary>Every token in a file, by its DTCG path <c>group.name</c>.</summary>
    private static Dictionary<string, JsonElement> Tokens(JsonElement doc)
    {
        var tokens = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
        foreach (var group in doc.EnumerateObject().Where(g => !g.Name.StartsWith('$')))
            foreach (var token in group.Value.EnumerateObject().Where(t => !t.Name.StartsWith('$')))
                tokens[group.Name + "." + token.Name] = token.Value;
        return tokens;
    }

    [Fact]
    public void Every_dtcg_file_on_disk_is_listed_and_every_listed_file_exists()
    {
        var listed = Files().Select(f => f.File).ToList();
        var onDisk = Directory.GetFiles(TokensDir, "Sedna.UI.tokens.dtcg*.json").Select(Path.GetFileName).ToList();

        Assert.Equal(listed.Count, listed.Distinct(StringComparer.Ordinal).Count());
        Assert.Equal(listed.OrderBy(f => f, StringComparer.Ordinal), onDisk.OrderBy(f => f, StringComparer.Ordinal));
        foreach (var (file, _, _, load) in Files())
            foreach (var before in load)
                Assert.True(listed.IndexOf(before) < listed.IndexOf(file),
                    $"{file} loads {before}, which the manifest lists after it.");
    }

    [Fact]
    public void Every_token_has_a_type_and_a_value_of_that_types_shape()
    {
        var problems = new List<string>();
        foreach (var (file, _, _, _) in Files())
            foreach (var (path, token) in Tokens(Load(file)))
            {
                if (!token.TryGetProperty("$value", out var value))
                {
                    problems.Add($"{file} {path}: no $value");
                    continue;
                }
                if (!token.TryGetProperty("$type", out var type) || !Types.Contains(type.GetString() ?? ""))
                {
                    problems.Add($"{file} {path}: no $type, or one the format does not define");
                    continue;
                }
                if (!Shaped(type.GetString()!, value))
                    problems.Add($"{file} {path}: {value.GetRawText()} is not a {type.GetString()}");
            }

        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
    }

    [Fact]
    public void Every_alias_resolves_to_a_token_of_the_same_type_in_the_files_loaded_with_it()
    {
        var problems = new List<string>();
        var aliases = 0;
        foreach (var (file, _, _, load) in Files())
        {
            var inForce = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
            foreach (var each in load.Append(file))
                foreach (var (path, token) in Tokens(Load(each)))
                    inForce[path] = token;

            foreach (var (path, token) in Tokens(Load(file)))
            {
                var type = token.GetProperty("$type").GetString()!;
                var value = token.GetProperty("$value");
                var references = new List<(string Reference, string Type)>();
                if (value.ValueKind == JsonValueKind.String && Alias.IsMatch(value.GetString()!))
                    references.Add((value.GetString()!, type));
                if (type == "shadow")
                    foreach (var layer in value.ValueKind == JsonValueKind.Array ? value.EnumerateArray().ToList() : [value])
                        if (layer.ValueKind == JsonValueKind.Object
                            && layer.GetProperty("color") is { ValueKind: JsonValueKind.String } colour)
                            references.Add((colour.GetString()!, "color"));

                foreach (var (reference, expected) in references)
                {
                    aliases++;
                    var target = Alias.Match(reference).Groups["path"].Value;
                    if (!inForce.TryGetValue(target, out var resolved))
                        problems.Add($"{file} {path}: {reference} names no token in {file} or the files it loads");
                    else if (resolved.GetProperty("$type").GetString() != expected)
                        problems.Add($"{file} {path}: {reference} is a {resolved.GetProperty("$type").GetString()}, not a {expected}");
                }
            }
        }

        Assert.True(aliases > 0, "No alias found at all: the generator stopped writing references.");
        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
    }

    [Fact]
    public void Each_file_carries_every_token_its_block_declares_and_nothing_it_does_not()
    {
        using var export = JsonDocument.Parse(File.ReadAllText(Assets.TokensPath));
        var files = Files();
        var problems = new List<string>();

        foreach (var block in export.RootElement.GetProperty("blocks").EnumerateArray())
        {
            var selector = block.GetProperty("selector").GetString()!;
            var media = block.GetProperty("media").ValueKind == JsonValueKind.Null ? null : block.GetProperty("media").GetString();
            var match = files.Where(f => f.Selector == selector && f.Media == media).ToList();
            if (match.Count != 1)
            {
                problems.Add($"{media} {selector}: {match.Count} DTCG files, not one");
                continue;
            }

            var doc = Load(match[0].File);
            var tokens = Tokens(doc);
            var cssOnly = Meta(doc).GetProperty("cssOnly").EnumerateObject().Select(p => p.Name).ToHashSet(StringComparer.Ordinal);
            var declared = block.GetProperty("tokens").EnumerateObject().ToList();

            foreach (var property in declared)
            {
                var leaf = property.Name[2..];
                var path = leaf.Split('-')[0] + "." + leaf;
                var css = property.Value.GetString()!;
                if (tokens.TryGetValue(path, out var token))
                {
                    // A literal colour is the same colour in both exports.
                    if (Regex.IsMatch(css, "^#[0-9a-fA-F]{6}$"))
                        Assert.Equal(css.ToLowerInvariant(), token.GetProperty("$value").GetProperty("hex").GetString());
                }
                else if (!cssOnly.Contains(leaf))
                    problems.Add($"{match[0].File}: {property.Name} is neither a token nor listed under cssOnly");
            }

            // What the block does not declare is there only because CSS computes it from
            // something the block changed, and it says so.
            var names = declared.Select(p => p.Name[2..]).ToHashSet(StringComparer.Ordinal);
            foreach (var (path, token) in tokens)
                if (!names.Contains(path[(path.IndexOf('.', StringComparison.Ordinal) + 1)..])
                    && !(token.TryGetProperty("$extensions", out var ext) && ext.TryGetProperty(Extension, out var mine)
                         && mine.TryGetProperty("css", out _)))
                    problems.Add($"{match[0].File}: {path} is not declared in {media} {selector} and is not computed");
        }

        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
    }

    private static bool Shaped(string type, JsonElement value)
    {
        if (value.ValueKind == JsonValueKind.String && Alias.IsMatch(value.GetString()!)) return true;

        return type switch
        {
            "color" => Colour(value),
            "dimension" => Measure(value, "px", "rem"),
            "duration" => Measure(value, "ms", "s"),
            "number" => value.ValueKind == JsonValueKind.Number,
            "fontWeight" => value.ValueKind is JsonValueKind.Number or JsonValueKind.String,
            "fontFamily" => value.ValueKind == JsonValueKind.String
                            || (value.ValueKind == JsonValueKind.Array
                                && value.EnumerateArray().All(f => f.ValueKind == JsonValueKind.String)),
            "cubicBezier" => value.ValueKind == JsonValueKind.Array
                             && value.GetArrayLength() == 4
                             && value.EnumerateArray().All(p => p.ValueKind == JsonValueKind.Number),
            "shadow" => value.ValueKind == JsonValueKind.Array
                ? value.GetArrayLength() > 0 && value.EnumerateArray().All(Shadow)
                : Shadow(value),
            _ => false,
        };
    }

    private static bool Colour(JsonElement value)
    {
        if (value.ValueKind != JsonValueKind.Object) return false;
        if (value.GetProperty("colorSpace").GetString() != "srgb") return false;
        var components = value.GetProperty("components");
        if (components.GetArrayLength() != 3
            || components.EnumerateArray().Any(c => c.GetDouble() is < 0 or > 1)) return false;
        if (value.TryGetProperty("alpha", out var alpha) && alpha.GetDouble() is < 0 or > 1) return false;
        return !value.TryGetProperty("hex", out var hex) || Regex.IsMatch(hex.GetString() ?? "", "^#[0-9a-f]{6}$");
    }

    private static bool Measure(JsonElement value, params string[] units) =>
        value.ValueKind == JsonValueKind.Object
        && value.TryGetProperty("value", out var number) && number.ValueKind == JsonValueKind.Number
        && value.TryGetProperty("unit", out var unit) && units.Contains(unit.GetString());

    private static bool Shadow(JsonElement layer)
    {
        if (layer.ValueKind != JsonValueKind.Object) return false;
        if (!layer.TryGetProperty("color", out var colour)) return false;
        var colourOk = colour.ValueKind == JsonValueKind.String ? Alias.IsMatch(colour.GetString()!) : Colour(colour);
        return colourOk && new[] { "offsetX", "offsetY", "blur", "spread" }
            .All(p => layer.TryGetProperty(p, out var d) && Measure(d, "px", "rem"));
    }
}
